import { Router } from 'express';
import { createLogger } from '../utils/logger';
import { parseLaunchableUrl } from '../utils/launchableUrl';
import {
  IntegrationsClient,
  isIntegrationProvider,
} from '../services/IntegrationsClient';
import type { IntegrationBrowserLaunchResponse } from '../types/api-responses';

const log = createLogger('IntegrationsRoutes');

export const createIntegrationsRouter = ({
  openExternalUrl,
}: {
  openExternalUrl: (url: string) => Promise<unknown>;
}) => {
  const router = Router();

  router.get('/integrations', async (_req, res) => {
    const result = await new IntegrationsClient().listIntegrations();
    if (result.status === 'error') {
      return res.status(502).json({ error: result.message });
    }
    return res.json({ integrations: result.integrations });
  });

  router.post('/integrations/:provider/browser-launches', async (req, res) => {
    const provider = req.params.provider;
    if (!isIntegrationProvider(provider)) {
      return res.status(400).json({ error: 'Unknown provider' });
    }
    const result = await new IntegrationsClient().connect(provider);
    if (result.status === 'error') {
      log.warn(`Connect failed for ${provider}:`, result.message);
      return res.status(502).json({ error: result.message });
    }
    const launchUrl = parseLaunchableUrl(result.authUrl);
    if (!launchUrl) {
      log.warn(`Rejected an unsafe ${provider} sign-in page`);
      return res.status(502).json({ error: `Could not connect ${provider}` });
    }
    try {
      await openExternalUrl(launchUrl);
    } catch {
      log.warn(`Could not open the ${provider} sign-in page`);
      return res.json({
        authUrl: result.authUrl,
        isLaunched: false,
      } satisfies IntegrationBrowserLaunchResponse);
    }
    return res.json({
      authUrl: result.authUrl,
      isLaunched: true,
    } satisfies IntegrationBrowserLaunchResponse);
  });

  router.delete('/integrations/:provider', async (req, res) => {
    const provider = req.params.provider;
    if (!isIntegrationProvider(provider)) {
      return res.status(400).json({ error: 'Unknown provider' });
    }
    const result = await new IntegrationsClient().disconnect(provider);
    if (result.status === 'error') {
      log.warn(`Disconnect failed for ${provider}:`, result.message);
      return res.status(502).json({ error: result.message });
    }
    return res.json({ success: true });
  });

  return router;
};
